function pokemonRomPreset(game) {
  if (!game) return null;
  const entry = BUNDLED_ROMS.find(rom =>
    game.id === (game.type === 2 ? "2" : "1") + "-" + rom.size + "-" +
       rom.checksum.toString(16).toUpperCase().padStart(8, "0"));
  return entry ? { id: entry.id, ...PK_CHEAT_INFO[entry.id] } : null;
}
