function pokemonCheatPresets(info, speciesId = 25) {
  if (!info) return [];
  let presets;
  if (info.family === "frlg") {
    presets = PK_GBA_ITEMS.map(entry => ({ ...entry }));
    presets.push(info.id === "pokemon-leafgreen" ? PK_LEAFGREEN_XP : PK_FIRERED_XP);
  } else if (info.family === "emerald") presets = PK_EMERALD.map(entry => ({...entry}));
  else if (info.family === "rs") presets = PK_RS.map(entry => ({...entry}));
  else if (info.family === "crystal") presets = PK_CRYSTAL.map(entry=>({...entry}));
  else presets = PK_GS.map(entry=>({...entry}));
  if (info.family === "frlg" && info.revision === 1) {
    // A versão 1.1 exige códigos próprios para os itens. Não reutilizar os de 1.0.
    presets = presets.filter(p => !["rare", "master", "maxrevive"].includes(p.id));
  }
  presets.push(...PK_EXPANDED.filter(([fam, only]) =>
    fam === info.family && (!only || (only === "rev1" && info.revision === 1)))
    .map(([, , x]) => ({...x, caution: x.caution || (info.family === "frlg" && info.modified)})));
  const numeric = Math.max(1, Math.min(info.family === "gs" || info.family === "crystal" ? 251 : 411, Number(speciesId) || 25));
  const species = POKEMON_SPECIES.find(([id]) => id === numeric) || POKEMON_SPECIES[24];
  let master=[];
  let wildCode;
  let caution=false;
  if (info.family === "crystal") wildCode = [PK(4,"01" + species[0].toString(16).toUpperCase().padStart(2,"0") + "04D2")];
  else if (info.family === "gs") wildCode = [PK(4,"01" + species[0].toString(16).toUpperCase().padStart(2,"0") + "EDD0")];
  else {
    const base = info.family === "frlg" ? "83007CEE " : info.family === "emerald" ? "83007CF6 " : "83007D22 ";
    wildCode = [PK(1,base + species[0].toString(16).toUpperCase().padStart(4,"0"))];
    caution = info.family === "rs" || info.modified || info.revision === 1;
    if (info.id === "pokemon-firered") master = [PK(3,"4D83B1BF E0F5F507"),PK(3,"8E883EFF 92E9660D"),PK(3,"B6C5368A 08BE8FF4"),PK(3,"90B4977C C0151DC2")];
    else if (info.id === "pokemon-leafgreen") master = [PK(1,"0000BE99 000A"),PK(1,"1004448C 0007")];
    else if (info.id === "pokemon-firered-completo") master = [PK(1,"000014D1 000A"),PK(1,"1003DAE6 0007")];
    else if (info.family === "emerald") master = [PK(1,"00006FA7 000A"),PK(1,"1006AF88 0007")];
    else master = [PK(1,"0000B138 000A"),PK(1,"1003A82A 0007")];
  }
  presets.push({id:"wild", title:"Encontrar " + species[1], category:"Encontros", group:"wild-species", speciesId:species[0],
    detail:"Ative, inicie um encontro na grama ou água e desative após encontrar o Pokémon. Use apenas um modificador por vez. " +
      (master.length ? "O código mestre necessário é incluído automaticamente. " : "") + (caution ? "A revisão desta ROM pode exigir códigos alternativos." : ""),
    caution, codes:[...master,...wildCode] });
  return presets;
}
const POKEMON_CHEATS = Object.freeze({ species: POKEMON_SPECIES, rom: pokemonRomPreset, presets: pokemonCheatPresets });
